# -*- coding: utf-8 -*-
"""English translations, batch 6 (40 figures, incl. 耶稣基督)."""
EN = {
"书念妇人": dict(lesson="Generous hospitality and steadfast faith",
 summary="A wealthy Shunammite woman who took the initiative to build a guest room for Elisha; when her son died she went alone to find the prophet, refusing easy comfort, insisting the prophet come himself—and her son was raised.",
 witness="Her son died; she laid him on the bed and told her husband: all is well. Then she rode a donkey to the prophet, not stopping along the way. When Elisha's servant asked, is it well? she said: it is well. She did not break down on the road; she held on until she saw the prophet, then wept at his feet. Faith is not denying pain, but knowing where to find the answer.",
 follow=["Recognizing Elisha as a man of God, building a roof chamber with bed and table for him, generously hosting without being asked (2 Kgs 4:9-10)","When her child suddenly died, not detouring or accepting easy comfort, going straight to the prophet: 'I will not leave you' (2 Kgs 4:30)","In her deepest pain still declaring in faith 'all is well,' holding on to the end, finally seeing her son raised"],
 caution=[],
 applications=["Do you have the generosity to 'build a guest room for the prophet'? Provide proactively for God's work","Faith is knowing where to go—where do you go in crisis today?","'It is well' is not a lie, but a faith-declaration of God's sovereignty"],
 prayer="Lord, the Shunammite built a guest room for Your servant and ran straight to You in crisis. Help me have such a generous heart, and in crisis know to come straight to You. Amen."),
"拔示巴": dict(lesson="Transformation from tragedy to queen",
 summary="The woman David took by force; after her husband Uriah died she became David's wife, her first child died, she later bore Solomon, and finally became the mother who secured the throne for her son.",
 witness="She is the most innocent victim in the story—taken by power. Her first child died, the cost of David's sin. Then she bore Solomon. In David's old age, she wisely ensured Solomon's enthronement and became the queen mother. The entrance of tragedy is not the ending. God kept working in her broken story, and Solomon became the wisest king.",
 follow=["After the adversity of being taken by force and losing husband and son, still wisely protecting her son Solomon's future in the court","In later years steadily using her influence to bring about the enthronement of God's chosen Solomon (1 Kgs 1)"],
 caution=["In later years deeply involved in the power games of succession at court (1 Kgs 1-2), reminding us to keep pure motives amid influence","(Her experience of being taken by force also warns) how important it is to set boundaries early and avoid danger when power and temptation draw near"],
 applications=["Is the greatest tragedy in your life an ending, or a place God keeps working?","Bathsheba's story: God can still work amid the harm caused by others' sins","Choose to move forward today, rather than stay in the story of the hurt"],
 prayer="Lord, Bathsheba's story is a tragedy, yet You still worked in it. Thank You for not giving up on me because of how others have hurt me. Help me too see You still working in the most broken places. Amen."),
"撒罗米": dict(lesson="A woman disciple who accompanied the cross and resurrection",
 summary="The wife of Zebedee and mother of James and John, who once sought high positions for her sons, yet was also one of the women standing by the cross and among the first at the empty tomb.",
 witness="She once asked Jesus to let her two sons sit at His right and left. Jesus said: you do not know what you are asking. Then at the cross, she stood there. She watched her sons' Master be crucified, and still stayed. Then she became one of the first witnesses of the resurrection. From seeking high position to standing beneath the cross—this is real discipleship growth.",
 follow=["Growing from seeking high position to being a disciple willing to stand beneath the cross","Becoming an early witness of the resurrection"],
 caution=["Seeking high positions for her sons, beyond God's order of choosing"],
 applications=["Have you too sought high position for yourself or family? How will you respond to Jesus' 'you do not know what you ask'?","A mark of disciple maturity: from pursuing status to willing to share in suffering","Stand beneath the cross today—do not leave Jesus in suffering"],
 prayer="Lord, Salome went from seeking high position to standing beneath the cross. Help me too grow from pursuing status to being willing to walk the road of suffering with You, until I see the resurrection. Amen."),
"以利沙伯": dict(lesson="Waiting heard by God even in old age",
 summary="The wife of the priest Zechariah, old and barren, who yet conceived John the Baptist; when Mary visited, she was filled with the Spirit and spoke a blessing over Mary and the child in her womb.",
 witness="She and her husband were both righteous, blameless in keeping God's commandments—yet she was barren and advanced in years. God had not forgotten her; the time had simply not come. When Mary visited, the baby leaped in her womb, and she was filled with the Spirit and said: blessed are you among women! She was the first to openly declare that Mary carried 'the mother of my Lord.' Old age's waiting yielded a prophet's birth.",
 follow=["After long waiting, still righteous and blameless","Boldly declaring God's word when filled with the Spirit","Becoming a support to Mary in a difficult time"],
 caution=[],
 applications=["Has your waiting made you 'blameless'—waiting faithfully?","Sometimes God's answer comes only in old age, but it surely comes","Is there a chance today to speak a word of blessing over another's faith, like Elizabeth?"],
 prayer="Lord, Elizabeth waited a lifetime, and You gave her a prophet in old age. Help me remain righteous and blameless through long waiting, trusting Your time will surely come. Amen."),
"西庇太的雅各": dict(lesson="The first apostle to be martyred",
 summary="John's brother, called by Jesus to leave his nets and follow; the first of the twelve apostles to be martyred for the faith, killed by Herod Agrippa.",
 witness="He and his brother John were once called 'sons of thunder,' and once asked Jesus to let them sit in high positions. But in the end he became the first apostle to shed blood for the faith. From a son of thunder to a martyr—this is the deepest fulfillment of discipleship. God sometimes seals faith with a life, and his death did not make the church retreat, but made believers braver.",
 follow=["Growing from a hot-tempered son of thunder into a witness willing to be martyred","Faithful to the end, not retreating because of the cost"],
 caution=["Early pride in seeking high position"],
 applications=["Can your faith withstand the test of cost?","The growth trajectory from son of thunder to martyr: how is God shaping you?","Pray today for persecuted brothers and sisters"],
 prayer="Lord, James son of Zebedee was the first apostle martyred for You. Help me have such faithfulness—not impulsive emotion, but real commitment, willing to pay the cost for You. Amen."),
"腓力": dict(lesson="Bringing people to Jesus",
 summary="A man of Bethsaida among the first called by Jesus, who at once found Nathanael and said: we have found the one Moses wrote about. Tested in faith before the feeding of the five thousand, at the Last Supper he said: Lord, show us the Father.",
 witness="Philip's first appearance was to find a friend: we have found him. His first response was to share. Before feeding the five thousand, Jesus asked him: where shall we buy bread for these? Philip calculated: two hundred denarii of bread would not be enough. He was a practical calculator, and a true seeker. He asked: Lord, show us the Father—the deepest longing in every seeker's heart.",
 follow=["His first response was to find a friend and share the good news","Having a true spiritual longing: Lord, show us the Father"],
 caution=["Before a miracle, tending to calculate possibilities with human eyes"],
 applications=["After you came to know Jesus, who was the first person you went to?","Whom can you go to today and say: I have found Him?","Philip's question is your question: God, let me know You more"],
 prayer="Lord, Philip found You and at once went to share with a friend. Help me have the same response—on meeting You, to go find people. Amen."),
"巴多罗买": dict(lesson="A true Israelite with no deceit",
 summary="That is, Nathanael, whom Jesus praised as 'a true Israelite, in whom there is no deceit.' At first he doubted whether anything good could come from Nazareth, but after Philip persuaded him to come, he at once recognized Jesus as the Son of God.",
 witness="Jesus saw him coming and said: behold, a true Israelite, in whom there is no deceit. Nathanael asked: how do You know me? Jesus said, I saw you under the fig tree. That one sentence was enough. A heart without deceit is worthy of God's complete knowing. He was fully known, and therefore fully trusted.",
 follow=["A heart without deceit, the most basic character of faith","Willing to be persuaded by a friend to come and verify in person"],
 caution=["Early regional prejudice: can anything good come from Nazareth?"],
 applications=["Are you willing to be 'without deceit' before God—honestly showing your true state?","Prejudice keeps us from meeting God; lay down one prejudice today","Fully known yet still loved: this is the gospel"],
 prayer="Lord, You saw Nathanael under the fig tree. You also see all my hidden places. Help me, like him, to be fully known and still fully trust You. Amen."),
"马太": dict(lesson="Transformation from tax collector to apostle",
 summary="Levi the tax collector, who at Jesus' call at once left the tax booth and followed, then held a great banquet to welcome Jesus, and later wrote the first of the four Gospels—the Gospel of Matthew.",
 witness="Jesus passed the tax booth, saw him, and said: follow Me. He rose and followed. This is Scripture's shortest yet most complete response to a call. A tax collector despised by society, rejected by all, yet chosen by Jesus. His first response was to throw a feast, inviting a crowd of sinners. Jesus came not to call the righteous but sinners. Matthew's story is the truest living commentary on that sentence.",
 follow=["Sitting at the tax booth, called by 'follow Me,' he left a lucrative profession and at once rose to follow (Matt 9:9)","Then holding a great banquet at home, inviting many tax collectors and sinners to meet Jesus, sharing the joy of grace with his own kind (Luke 5:29)","The forgiven tax collector later wrote the first Gospel, Matthew, leaving an eternal witness"],
 caution=[],
 applications=["When Jesus calls you, what is the 'tax booth' hardest to leave?","Has your story of grace drawn others to know Jesus?","Pray today for someone marginalized by society"],
 prayer="Lord, Matthew was seen and called by You at the tax booth. Help me hear Your voice at my own 'tax booth' and rise to follow at once. Amen."),
"奋锐党的西门": dict(lesson="Zeal transformed from political to spiritual",
 summary="A Zealot, originally devoted to a political movement to drive out Rome by force, who after Jesus' call directed his zeal entirely to the kingdom of God.",
 witness="He was on the list of the twelve apostles together with Matthew—one a tax collector for the Roman Empire, the other a revolutionary resisting Rome. Jesus deliberately put these two together. This is the most unlikely reconciliation. The mystery of the kingdom: people who hated each other became brothers through Jesus. His zeal did not disappear; only its object changed from politics to God's kingdom.",
 follow=["Turning the political fervor that once sought to resist Rome by force entirely to the use of God's kingdom","Able to be among the twelve apostles with Matthew the tax collector, from the once-hostile 'enemy camp,' turning enemies into brothers in Christ"],
 caution=[],
 applications=["Has your passion been redirected by God's kingdom?","Is there someone in the church you originally could not accept? How does Jesus see them?","True revolution is the change of the heart"],
 prayer="Lord, Simon the Zealot's zeal was redirected by You. Help me give all my passion to You, letting You decide where it should point. Amen."),
"达太": dict(lesson="The faithfulness of an unknown apostle",
 summary="Also called Judas (not Iscariot), who at the Last Supper asked Jesus: Lord, why will You reveal Yourself to us and not to the world?—voicing the doubt in many believers' hearts.",
 witness="He appears only in the apostle list and one question. But that question is no small one: why reveal Yourself only to us? Jesus' answer was: whoever loves Me, My Father will love him, and We will come to him and make Our home with him. Thaddaeus represents every unknown, unrecorded disciple who truly followed. God's kingdom needs not only Peter and Paul, but also Thaddaeus.",
 follow=["At the Last Supper daring to ask his true heart-doubt 'Lord, why reveal Yourself to us and not to the world,' voicing what many felt (John 14:22)","In a position of minimal record and no spotlight, still quietly following faithfully to the end"],
 caution=[],
 applications=["Is there a doubt in your heart you've never asked God? Ask it today","The kingdom needs unknown, faithful people—are you willing to be one?","Ordinary following is also following"],
 prayer="Lord, Thaddaeus asked the question many of us hold in our hearts. Help me have courage to ask my true doubts before You, then quietly listen to Your answer. Amen."),
"马提亚": dict(lesson="Chosen by God to fill the gap",
 summary="Chosen before Pentecost as the twelfth apostle to replace Judas, having followed from Jesus' baptism to His resurrection, becoming an apostle simply by God's choosing.",
 witness="Peter said: one must be chosen from those who have accompanied us. Matthias was such a man—always following, never in the spotlight, never self-promoting, just there. Then God's choice fell on him. His story tells us: faithful following is itself the qualification. You need not be famous, only present.",
 follow=["'Accompanying the apostles' from Jesus' baptism to ascension, long following in obscurity, not leaving for lack of title (Acts 1:21-22)","Calmly accepting God's choice by lot, numbered among the apostles, faithfully taking up the vacancy"],
 caution=[],
 applications=["Are you willing to be a Matthias—always present, quietly following?","A faithful witness is the whole journey from Jesus' baptism to resurrection","Hold your post today, not retreating because no one notices"],
 prayer="Lord, Matthias was always present, and then God's choice fell on him. Help me not pursue the spotlight, but only seek to be faithfully present. Your choosing is in Your hands; I need only follow. Amen."),
"亚比央": dict(lesson="God's grace surpasses the fathers' failures",
 summary="Son of Rehoboam, the second king of Judah, who imitated his father's sins with a divided heart, yet God preserved his throne for David's sake.",
 witness="God still showed grace in Abijah's weak life, because His promise to David does not change. Grace depends not on our performance, but on God's faithfulness.",
 follow=["God's grace surpasses personal failure"],
 caution=["A heart not wholly devoted to God","Imitating his father's sins"],
 applications=["God's grace is still effective in your weakest place","Don't resign yourself to a family pattern—you can break the cycle"],
 prayer="Lord, Abijah's story reminds me that Your grace does not depend on my perfection. Thank You for showing me grace for Jesus' sake. Amen."),
"约兰": dict(lesson="Marriage relationships affect spiritual direction",
 summary="A king of Judah, son of Jehoshaphat, who married Ahab's daughter, walked in the way of Israel's kings, killed his brothers, and led Judah into rebellion against God.",
 witness="He married the wrong spouse and walked the wrong path. Spiritual relationships deeply affect the direction of our faith.",
 follow=[],
 caution=["Marrying a pagan, wicked woman and turning from God","Killing his brothers to consolidate power","Leading the nation into idolatry"],
 applications=["The most intimate relationship will deeply affect your faith's direction","Examine: are those closest to you drawing you toward God or away?"],
 prayer="Lord, help me choose intimate relationships that bring me closer to You, and help me be one who leads others back to You. Amen."),
"亚哈谢": dict(lesson="Wrong counselors bring destruction",
 summary="A king of Judah influenced by his mother Athaliah and Ahab's house to do evil, who joined Israel's king Joram in battle and was killed by Jehu.",
 witness="His mother and counselors led him to destruction. We cannot grow alone; who we choose as our spiritual mentors is crucial.",
 follow=[],
 caution=["'Walking in the way of Ahab's house,' doing evil because his mother Athaliah was his counselor and instigator (2 Chr 22:3-4)","Allying with the wicked king Joram, and consequently being killed together by Jehu—keeping company with the wicked and sharing their ruin"],
 applications=["Who are your main spiritual influences? Are they guiding you toward God?","Identify and distance yourself from influences drawing you from God"],
 prayer="Lord, help me carefully choose spiritual mentors, and protect me from the harm of wrong influences. Amen."),
"亚们": dict(lesson="Humility and pride bring different ends",
 summary="Son of Manasseh, a king of Judah, who unlike his father Manasseh's late humility and repentance, instead did evil all the more, and was killed by his servants after only two years.",
 witness="His father Manasseh repented, but the son Amon did not learn his father's post-repentance humility, only inheriting his father's sins. The example of repentance must be received to take effect.",
 follow=[],
 caution=["Imitating his father Manasseh's early evil, but not learning his father's late humility and repentance, 'not humbling himself before the LORD' (2 Chr 33:23)","Sin upon sin, killed by his servants after only two years on the throne—do not merely inherit the previous generation's faults while missing their repentance"],
 applications=["Have you truly received the lesson of the previous generation's repentance?","Humility can be chosen; pride can be chosen too"],
 prayer="Lord, help me not only see my predecessors' failures, but truly receive their lesson of repentance, walking the road of humility. Amen."),
"约哈斯": dict(lesson="A brief opportunity requires real commitment",
 summary="Son of Josiah, who reigned only three months before being deposed by Pharaoh Neco and taken to Egypt, doing evil in the LORD's eyes.",
 witness="After Josiah died, the son did not inherit his father's spirit. A spiritual legacy must be actively received by the next generation to continue.",
 follow=[],
 caution=["His devout father Josiah had just died in battle, yet within three months on the throne he 'did evil in the LORD's eyes,' not inheriting his father's faith (2 Kgs 23:32)","Quickly deposed by Pharaoh and taken captive to Egypt, dying in a foreign land—a spiritual legacy is not automatically inherited; each must hold to it personally"],
 applications=["A spiritual legacy is not automatically passed on; it must be actively chosen and received","What have you received from your faith predecessors? Have you given anything up?"],
 prayer="Lord, help me treasure the spiritual legacy received from devout predecessors, not casting it away lightly. Amen."),
"约雅敬": dict(lesson="Resisting God's word must finally fail",
 summary="A king of Judah who burned Jeremiah's scroll, rejected God's word, and finally submitted at Babylon's first invasion—a warning against opposing God's word.",
 witness="He took a knife and cut Jeremiah's scroll, throwing it piece by piece into the fire. This is one of the most arrogant responses in human history—burning God's word verse by verse. And the result? God's word was fulfilled to the letter.",
 follow=[],
 caution=["Using the king's penknife to cut Jeremiah's prophetic scroll piece by piece and burn it in the brazier, openly despising God's word (Jer 36:23)","Rejecting the prophet's repeated warnings, yet God's word could not be burned up—Jeremiah rewrote it with additions (Jer 36:32)","Building luxurious palaces for himself by exploiting the people, rebuked for 'caring only for greed and shedding innocent blood' (Jer 22:13-17)"],
 applications=["Are you avoiding a passage of Scripture because it makes you uncomfortable?","God's word does not lose effect because you reject it—it only makes you face the consequences faster"],
 prayer="Lord, help me take Jehoiakim as a warning, coming to Your word with a humble, open heart, not resisting what You say to me. Amen."),
"约雅斤": dict(lesson="God still has grace in exile",
 summary="One of Judah's last kings, who reigned only three months before being taken to Babylon, and in old age was released and treated well in Babylon—a small signal of grace surpassing judgment.",
 witness="He was imprisoned in Babylon for thirty-seven years, yet in old age was released and treated kindly by the Babylonian king. Even in the longest judgment, God still kept a thread of grace and hope.",
 follow=["After decades of exile, God moved the Babylonian king to treat him well, lift up his head, and let him dine at the king's table for life—remembered even in judgment (2 Kgs 25:27-30)"],
 caution=["Though reigning only three months, still 'did evil in the LORD's eyes,' inheriting the royal house's corruption (2 Kgs 24:9)"],
 applications=["What is your current 'exile' situation? Trust that God still has grace within it","The longest wait also has a turning point arranged by God"],
 prayer="Lord, Jehoiachin was treated kindly after thirty-seven years. Help me trust that even in long waiting and judgment, You still remember me and keep grace in reserve for me. Amen."),
"西底家": dict(lesson="Weak compromise is more dangerous than firm refusal",
 summary="Judah's last king, who privately consulted Jeremiah many times but dared not openly obey, compromised in fear, watched his sons killed, then had his eyes gouged out as the southern kingdom fell.",
 witness="He went privately to Jeremiah and asked: is there a word from God? He knew God's word, yet dared not act on it. Weakly knowing without doing is sometimes more tragic than firm refusal. His eyes saw his sons killed, then went blind forever—his last memory was the most horrible one.",
 follow=[],
 caution=["Knowing God's word yet not daring to act for fear of people","Repeatedly compromising under political pressure","Finally so weak as to be powerless to make any meaningful choice"],
 applications=["Do you have a Zedekiah-pattern of 'privately consulting God but publicly compromising'?","Weakly conforming to the world sometimes costs more than openly refusing"],
 prayer="Lord, protect me from becoming Zedekiah—knowing Your word yet not daring to act for fear of people. Give me courage to obey openly where I know Your will. Amen."),
"拿答": dict(lesson="The cost of sin is never late",
 summary="The second king of the north, son of Jeroboam, who continued his father's sins and was murdered by Baasha after only two years on the throne, with Jeroboam's house wiped out.",
 witness="He inherited his father's sins, and inherited his father's judgment. The cost of sin may be delayed, but never canceled.",
 follow=[],
 caution=["Inheriting his father Jeroboam's idolatry of the golden calves, 'walking in the way of his father' (1 Kgs 15:26)","Killed by Baasha after only two years on the throne, with Jeroboam's whole house destroyed—unaddressed sin brings ruin to a whole family"],
 applications=["Don't think that God not judging immediately means God approves","A family's sin needs someone to actively break it—are you that person?"],
 prayer="Lord, help me not inherit my family's pattern of sin, but be the one who breaks the cycle and chooses to turn to You. Amen."),
"暗利": dict(lesson="Political achievement cannot mask spiritual failure",
 summary="A powerful king of the north who built the city of Samaria, achieved much politically and militarily, but spiritually did worse than those before him.",
 witness="In history he was a powerful king, but in God's eyes he 'did worse than all who were before him.' The world's ranking of success and God's evaluation can be completely opposite.",
 follow=[],
 caution=["Politically and militarily skilled, building Samaria as capital and founding a dynasty—how outwardly successful (1 Kgs 16:24)","Yet spiritually 'doing more evil than all before him,' his achievements unable to mask his corrupt forsaking of God (1 Kgs 16:25)","Paving the way for his son Ahab to marry Jezebel, introducing Baal worship to the north with far-reaching harm"],
 applications=["By what standard do you measure your life's success?","Which matters more to you—God's evaluation or the world's?"],
 prayer="Lord, help me not measure success by the world's standard, but see my life's value and direction through Your eyes. Amen."),
"耶户": dict(lesson="Zealously carrying out God's command yet with a divided heart",
 summary="Anointed by God to overthrow Ahab's house, he thoroughly eradicated Baal worship, but still walked in Jeroboam's sins, his heart not wholly devoted to God.",
 witness="God praised him for carrying out His command, yet also said his heart was not wholly devoted. Zeal for God's work does not equal a heart fully turned to God. Faithfulness in action and faithfulness of heart both need examination.",
 follow=["Bravely executing God's mission of judgment","Thoroughly eliminating Baal worship"],
 caution=["Still walking in Jeroboam's sins, his heart not wholly devoted","More zealous for the work than for God Himself"],
 applications=["Is your spiritual zeal a heartfelt love of God, or the satisfaction of completing a task?","Examine: what is my motive in serving?"],
 prayer="Lord, do not let me become Jehu—zealous for Your work, yet my heart not wholly turned to You. Help me love You from the heart, not merely complete religious tasks. Amen."),
"约哈斯（北）": dict(lesson="Crying to God in suffering is the start of softening",
 summary="King of the north, son of Jehu, who during his reign cried to God amid Aramean oppression; God heard and delivered, but he still did not finally forsake idols.",
 witness="At the depth of suffering he 'entreated the LORD,' and God heard his prayer. Suffering can soften the hardest heart, prompting one to turn to God—even if that turning is not yet complete.",
 follow=["Knowing to turn to God in suffering"],
 caution=["Still not fully forsaking idols after crying out","Returning to the old way after being saved"],
 applications=["What is your first response in suffering? Turning to people, complaining, or turning to God?","An imperfect turning beats no turning, but God longs for you to fully return"],
 prayer="Lord, thank You for hearing even my imperfect cry. Help me not only seek You in suffering, but also not return to the old way after being saved. Amen."),
"约阿施（北）": dict(lesson="The strength of faith determines the scope of victory",
 summary="King of the north who visited the dying prophet Elisha; lacking faith, he shot only three arrows, and Elisha pointed out he could have won completely, but won only partial victory for lack of faith.",
 witness="Elisha had him shoot arrows; he shot only three times, then stopped. Elisha said: you should have shot five or six times, then you would have completely defeated Aram. The scope of your victory is directly related to the strength of your faith.",
 follow=["Going to seek and honor the prophet's word"],
 caution=["Insufficient faith, limited victory","Holding back his strength before God, limiting God's work"],
 applications=["Do you have a 'only three arrows' holding back before God?","What can you act on today with greater faith?"],
 prayer="Lord, do not let me be one who shoots only three arrows. Help me not hold back before You, but trust fully, so my faith's strength matches the blessing You are willing to give. Amen."),
"法老": dict(lesson="A hardened heart makes one miss the chance to repent",
 summary="King of Egypt who ten times rejected God's warnings through Moses, hardening his heart after each plague, finally perishing in the Red Sea—the most typical case in human history of hardness and rebellion.",
 witness="After each plague, God gave him a chance to repent, yet again and again he hardened his heart. Scripture says God hardened his heart—this is not God forcing him to sin, but God letting him fully display the hardness he already had. He was not forced toward destruction, but step by step chose to reject God.",
 follow=[],
 caution=["Hardening his heart after each suffering, unwilling to truly repent","Treating disaster as a problem solved rather than God's call","Returning to his old state at once after relief, pursuing the fleeing people"],
 applications=["What is God saying to you in suffering? Don't only seek relief; listen to God's voice","Examine whether you have a Pharaoh-cycle—seeking God in crisis, reverting after the crisis passes","True repentance is a change of direction, not only a change of feeling"],
 prayer="Lord, protect my heart from Pharaoh-like hardness. When You speak to me in any way, help me truly hear and truly respond, not forget Your voice once the suffering passes. Amen."),
"约押": dict(lesson="Talent and loyalty cannot mask the sin of killing for self-interest",
 summary="David's most capable general, who won countless battles and great honor, yet three times killed the innocent for self-interest (Abner, Absalom, Amasa), and was finally executed by Solomon per David's last will.",
 witness="He was loyal to David's kingship, but not to David's God. He could win every battle, yet lost the battle for his own soul. Talent and merit cannot excuse harming others for self-interest. His tragedy: he knew David's heart, yet repeatedly chose his own judgment over God's command.",
 follow=[],
 caution=["Killing Abner out of private grudge, against David's clear wish","Acting on his own in the Absalom matter, ignoring David's order to spare him","Backing the wrong political side, supporting Adonijah, and finally being purged"],
 applications=["Examine: do I, under the excuse of 'for your good' or 'efficiency,' override God and authority to do what I think is right?","The greater the talent, the more it needs the restraint of obedience—Joab's failure was not lack of ability, but lack of obedience","Loyalty must be to God's standard, not only to a person or a result"],
 prayer="Lord, Joab's life reminds me: no amount of talent and contribution can justify acting on self-will. Help me be more obedient where I am capable, not more autonomous. Amen."),
"迦得": dict(lesson="Faithfully conveying God's message of discipline is a prophet's most important duty",
 summary="David's seer, who faithfully brought David God's message of judgment over the census, accompanied David through his hardest moment of choosing the punishment, and later helped David establish temple worship.",
 witness="God gave David three options, and Gad faithfully brought the message without any sugarcoating. A prophet's duty is not to make people comfortable, but to let them hear God's voice. The hardest message often needs the most faithful messenger.",
 follow=["Faithfully bringing the message of discipline over David's census exactly as it was, without sugarcoating (2 Sam 24:11-13)","Accompanying David in the hardest moment of choosing the punishment, guiding him to build an altar and offer sacrifice, staying the plague (2 Sam 24:18)"],
 caution=[],
 applications=["Do you have a duty to speak a truth others don't want to hear? A prophet's faithfulness matters more than his popularity","God's message of discipline always has room for mercy—Gad brought judgment, but also a choice"],
 prayer="Lord, Gad brought a hard message yet did not leave David. Help me, when I speak truth, also have Gad's accompaniment and faithfulness. Amen."),
"亚希雅": dict(lesson="God's word will surely come to pass; the prophet is only a faithful mouthpiece",
 summary="A prophet of Shiloh who tore his cloak into twelve pieces to prophesy the kingdom's division, giving ten pieces to Jeroboam; blind in old age, he still accurately prophesied the downfall of Jeroboam's house by God's word.",
 witness="In his youth he tore his cloak to prophesy; in old age, blind, he was still accurate. His eyes could not see, but God's word was clear in his heart. A true prophet relies not on insight, but on God's revelation.",
 follow=["Tearing a new garment into twelve pieces to prophesy the kingdom's division, faithfully conveying God's word regardless of who was in power (1 Kgs 11:30-31)","Blind in old age, still accurately declaring by God's word the downfall Jeroboam's house would suffer for its sin, faithful to the end (1 Kgs 14:4-11)"],
 caution=[],
 applications=["Are you willing to convey God's unpopular message?","God's word does not depend on the messenger's condition—Ahijah, blind, could still convey God's message"],
 prayer="Lord, Ahijah faithfully conveyed Your word at the most inconvenient time. Help me, whatever my circumstance, faithfully bring Your word to those who need it. Amen."),
"示玛雅": dict(lesson="A timely word from God can prevent unnecessary bloodshed",
 summary="A man of God who, after the kingdom's division, stopped Rehoboam from attacking the north, and later during Shishak's invasion brought God's word, leading the southern kingdom's king and officials to repent and be spared from total destruction.",
 witness="One word made an army of 180,000 lay down their weapons. God speaks through a prophet not to display authority, but to save lives. He brought God's word at the most tense political moments, and both times people obeyed—extremely rare.",
 follow=["At the kingdom's division, timely conveying God's word to stop Rehoboam from making war on the brother northern kingdom, averting civil war (1 Kgs 12:24)","During Shishak's invasion when the south was about to fall, conveying God's word of rebuke, leading king and officials to humble themselves and repent and be spared (2 Chr 12:5-7)"],
 caution=[],
 applications=["Have you, in some conflict, stopped unnecessary harm because you heard God's word?","A prophet's word can sometimes change everything in a short time—the key is someone willing to speak, and someone willing to listen"],
 prayer="Lord, one word from Shemaiah stopped a war. Help me keenly hear Your voice in conflict, and have courage to speak Your word, trusting Your word can change the situation. Amen."),
"米该雅": dict(lesson="Speak only what God says, even if four hundred say the opposite",
 summary="A prophet of Israel who, facing four hundred false prophets all speaking favorably, alone insisted on conveying God's true message—Ahab would fail—and was thrown into prison, but his prophecy came true.",
 witness="Four hundred prophets said: go up, you will surely win. He alone stood up and said: no. He knew what it meant. Struck on the face, thrown in prison, yet he said: if you ever return in peace, the LORD has not spoken through me. This is a prophet's backbone.",
 follow=["Facing four hundred false prophets unanimously flattering the king, alone insisting 'whatever the LORD says to me, that I will speak' (1 Kgs 22:14)","Knowing speaking truth meant prison and the bread of affliction, still not going along with the crowd, preferring isolation to compromise (1 Kgs 22:27)"],
 caution=[],
 applications=["When everyone says one direction, have you heard God say something different?","Micaiah's cost was prison—how great a cost are you willing to pay to speak truth?"],
 prayer="Lord, Micaiah stood alone against four hundred. Help me, when everyone says yes, still dare to speak Your true word, leaving the result to You. Amen."),
"俄底": dict(lesson="A prophet's word can also stop the cruelty of the victorious",
 summary="A prophet of Samaria who, when the northern kingdom greatly defeated the south and seized two hundred thousand captives, stepped out alone to stop it, demanding the captives be released; the leaders obeyed, and the captives were properly returned—one of Scripture's most moving humanitarian moments.",
 witness="He went out to meet the triumphant army and said: you have won, but God does not want you to destroy your brothers. One man, no army, no political standing, only God's word—and four leaders obeyed him, releasing all the captives. Sometimes God's word can change people's hearts in an instant.",
 follow=["At Israel's proudest moment of great victory and capturing 200,000 southern compatriots, stepping out alone to stop them: 'the LORD's anger is against you' (2 Chr 28:9-11)","Caring for the captives' humanitarian plight, bringing about their being given food and clothing and escorted home—one of the OT's most moving humanitarian moments"],
 caution=[],
 applications=["Do you have courage to speak God's required mercy when others celebrate victory?","Oded's message was not judgment, but a reminder—this gentle prophetic word also takes courage"],
 prayer="Lord, Oded alone stopped the suffering of two hundred thousand. Help me, when I have a chance to stop harm, have Oded's courage to step out and speak, trusting Your word can soften hearts. Amen."),
"耶稣基督": dict(lesson="He is the heart and end of all sixty-six books of Scripture—every Old Testament figure is His shadow, and the New Testament reveals His true person. He became flesh, fully identifying with human weakness; in Gethsemane He bowed in prayer, fully submitting to the Father's will; on the cross He bore the sin of all mankind; in the resurrection He declared death conquered. He is not only the best example—He is the source of power by which we can imitate any example at all.",
 summary="Jesus Christ, the eternal Son of God, existed before creation (John 1:1), became flesh at the center of time (John 1:14), was born of Mary in Bethlehem (Luke 2:7), grew up in Nazareth (Luke 2:51-52), began His ministry at about thirty, and proclaimed the gospel of the kingdom, healed the sick, cast out demons, and raised the dead in Galilee, Samaria, and Judea. He gathered the twelve disciples and taught the way of kingdom living through parables and the Sermon on the Mount. On the eve of Passover He instituted the Lord's Supper (Matt 26:26-28), prayed with sweat like drops of blood in Gethsemane (Luke 22:44), was betrayed by Judas, tried before Pilate, and died on the cross at Golgotha (John 19:30), rose on the third day (Luke 24:6), ascended after forty days (Acts 1:9), and will surely come again to judge the living and the dead (Rev 22:20). His life encompassed every human condition: poverty, rejection, loneliness, misunderstanding, betrayal, suffering, death—He experienced them all in person, and so He is a high priest fully able to sympathize with us (Heb 4:15-16).",
 witness="""The lesson of every figure in Scripture finds its complete prototype and fulfillment in Him:
What Adam lost, He came to restore as the last Adam (1 Cor 15:45);
Noah built an ark to save people; He saves all mankind by the cross;
Abraham was willing to offer Isaac; He is the true only Son who was offered (John 3:16);
Joseph was betrayed by his brothers yet became a channel of salvation; He was betrayed by a disciple yet became the Savior of the world;
Moses was a mediator and intercessor; He is the one Mediator (1 Tim 2:5);
David was a shepherd-king after God's heart; He is the Good Shepherd (John 10:11), David's greater Son (Matt 22:42-45);
Elijah grew weary in the wilderness and an angel fed him; He fasted forty days in the wilderness tempted, yet overcame every temptation;
Job questioned God in suffering; He cried from the cross 'My God, My God, why have You forsaken Me' (Ps 22:1; Matt 27:46)—the mark that He truly bore humanity's sense of abandonment;
Ruth said 'where you go, I will go'; He became flesh and entered the human condition, committing Himself more thoroughly than Ruth;
Jonah was three days in the fish's belly, foreshadowing His three days in the earth (Matt 12:40);
The suffering servant Isaiah 53 portrays is Him—'He was pierced for our transgressions, crushed for our iniquities.' He is not one of Scripture's many figures; He is the One to whom all the figures point.""",
 follow=["Perfect love: loving His disciples to the end, laying down His life for the sheep—'greater love has no one than this, that he lay down his life for his friends' (John 13:1; 15:13)","Self-denying humility: being in the form of God, He emptied Himself, taking the form of a servant, obedient to death (Phil 2:6-8)","Complete obedience to the Father: 'My food is to do the will of Him who sent Me' 'not My will, but Yours be done' (John 4:34; Luke 22:42)","Compassion and kindness: seeing the crowds harassed and helpless like sheep without a shepherd, He had compassion (Matt 9:36)","Holiness without sin: tempted in every way as we are, yet without sin, no deceit in His mouth (Heb 4:15; 1 Pet 2:22)","Gentleness and humility: 'I am gentle and humble in heart; take My yoke and learn from Me' (Matt 11:29)","Forgiveness: interceding on the cross for those who nailed Him, 'Father, forgive them' (Luke 23:34)","Prayerful closeness to the Father: withdrawing to the wilderness to pray before dawn, sometimes praying all night (Mark 1:35; Luke 5:16; 6:12)","Truth and honesty: 'I am the way, the truth, and the life,' being truth itself (John 14:6; 8:45-46)","A heart to serve: 'the Son of Man came not to be served but to serve, and to give His life as a ransom for many,' washing the disciples' feet (Mark 10:45; John 13:14)","Zeal for the Father's house: cleansing the temple, 'My Father's house shall be called a house of prayer' (John 2:17; Matt 21:13)","Trust and entrustment: suffering without retaliation, entrusting Himself to Him who judges justly (1 Pet 2:23)","Real emotion: weeping at Lazarus' tomb, sighing and weeping over Jerusalem (John 11:35; Luke 19:41)","Seeking the lost: the Son of Man came to seek and save the lost, leaving the ninety-nine to find the one (Luke 19:10; 15:4-7)","Receiving the rejected: dining with tax collectors and sinners, receiving the adulterous woman, the Samaritan woman, the robber on the cross (Luke 5:30-32; 23:43)","Wisdom and authority: teaching as one who had authority, so that all were amazed at His teaching (Matt 7:28-29)","Bravely facing the cross: setting His face resolutely toward Jerusalem, enduring the cross and scorning its shame for us (Luke 9:51; Heb 12:2)","Patience and endurance: like a lamb led to slaughter, silently bearing all mistreatment (Isa 53:7; 1 Pet 2:23)","Obedience to death accomplishing salvation: 'It is finished'; by one offering of Himself He perfected forever those being sanctified (John 19:30; Heb 10:10-14)","Resurrection victory and eternal intercession: death could not hold Him; ascended, He lives forever to intercede for us (Acts 2:24; Heb 7:25; 1 Tim 2:5)"],
 caution=[],
 applications=["The suffering, rejection, and failure you face now—He has experienced all of it. Heb 4:15 says He was 'tempted in every way as we are.' You are not facing it alone","Imitating any figure in Scripture, the ultimate goal is to know Him more. Joseph's forgiveness, David's repentance, Ruth's commitment—all these virtues are complete in Him","When you feel forsaken by God, remember He too cried 'My God, My God, why have You forsaken Me'—He walked through the darkness you're in, and came out of it","'Imitating Christ' is not mimicking a distant example by willpower, but abiding in Him (John 15:5)—the relationship of vine and branch, not student and teacher","Every figure you see in the Mirror is saying: 'One greater than I is coming'—He came, and He is Jesus"],
 prayer="Lord Jesus, You are the heart of Scripture, the end of all figures, the complete demonstration of all our lessons. Thank You for becoming flesh and entering our truest condition; thank You for Your prayer in Gethsemane, showing us the pattern of obedience; thank You for saying on the cross 'Father, forgive them,' showing us that love can still be given in the deepest pain; thank You for rising, showing us that the darkest death is not the end. Help me not only admire You, but abide in You, letting Your life flow out from within me, rather than my striving to imitate You from outside. You are Lord, You are Savior, and You are my truest companion today. Amen."),
"亚萨": dict(lesson="Crying honestly to God in the deepest spiritual confusion is true faith",
 summary="A musician and poet of David's time, appointed to lead the tabernacle's song worship, who composed 12 psalms. Psalm 73 is his honest cry in his greatest crisis of faith: why do the wicked prosper? He nearly stumbled, until he entered the sanctuary and found the answer.",
 witness="Psalm 73 says: my feet had almost slipped. He nearly lost his faith over seeing the wicked prosper. Then he said: until I entered the sanctuary of God; then I understood their end. It was not that God gave him a sermon, but that he entered God's presence. The way out of spiritual confusion is not more answers, but a truer presence.",
 follow=["Bringing his most honest spiritual confusion into God's presence","Leading the congregation in worship through song in real emotion","Not leaving amid doubt, but turning to God"],
 caution=[],
 applications=["Have you had a moment, like Asaph, of nearly stumbling over 'the wicked prosper'?","Confusion is not a failure of faith; honestly bringing confusion into God's presence is the answer"],
 prayer="Lord, Asaph nearly stumbled, yet entered the sanctuary and found the answer. Help me, in my deepest spiritual confusion, neither flee nor pretend all is well, but honestly come before You and find the way out in Your presence. Amen."),
"可拉的后裔": dict(lesson="Saved out of a family's judgment, becoming bearers of praise",
 summary="Korah was swallowed by the earth in the wilderness for rebellion, but his sons did not die with him (Num 26:11), later becoming temple musicians and poets who wrote 11 psalms, including Psalm 84 'my soul longs for Your courts' and Psalm 46 'God is our refuge.'",
 witness="Their father was swallowed alive by the earth for rebellion, yet they did not die—Numbers deliberately records this. People rescued from the edge of judgment wrote the deepest psalms of longing. Psalm 84 says: my soul longs, even faints. This is not praise in calm days; this is longing rising from the depths. Those who have been through danger have a different weight to their praise.",
 follow=["Surviving the family judgment, not inheriting their father's rebellion","Writing Scripture's most deeply affectionate psalm of longing (Ps 84) and most steadfast psalm of refuge (Ps 46)"],
 caution=[],
 applications=["Is there a 'Korah-like rebellion' in your family history? You can choose not to inherit it","The judgment God rescued you from can become the source of your deepest longing"],
 prayer="Lord, the sons of Korah were rescued from their father's judgment, yet without bitterness wrote the deepest longing. Help me too, amid family or past shadows, choose to long for You rather than inherit hatred. Amen."),
"犹大（耶稣兄弟）": dict(lesson="From unbelief to contending for the faith, grace changed his view of his brother",
 summary="Jesus' brother, who early did not believe in Jesus (John 7:5), became a believer after the resurrection (Acts 1:14), and later wrote the Epistle of Jude, urging believers to 'contend earnestly for the faith once delivered to the saints'—a model of transformation from family unbelief to apologist.",
 witness="He grew up with Jesus, yet did not believe He was the Messiah. Then the resurrection changed everything. Writing Jude, he said: I wanted to write about our common salvation, but I had to write this urgent letter—some are distorting grace. From doubting his own brother to contending for his brother's truth, only the resurrection can explain this change.",
 follow=["Becoming a member of the early church after the resurrection (Acts 1:14)","Writing the Epistle of Jude to contend for the faith","From family doubt to holding firm to the faith"],
 caution=[],
 applications=["Have you had an experience of once doubting, then utterly turning around? Jude's change was real","'Contend earnestly for the faith'—do you dare to speak up for what you believe?"],
 prayer="Lord, Jude once did not believe his own brother was the Christ. But the resurrection changed him into one who contended for the faith. Help me too, in faith, not only receive, but have the courage to stand for the truth when needed. Amen."),
"流便（雅各长子）": dict(lesson="The firstborn's status permanently lost through one impulsive act",
 summary="Jacob's firstborn, who had the birthright, yet lost it for lying with his father's concubine; when Joseph was sold he tried to rescue him but failed to intercept; he was the first to voice his conscience before Joseph. A complex figure whose impulse destroyed his birthright, yet who still had conscience at the critical moment.",
 witness="He had the title, but not the character to bear it. One impulsive sin permanently changed his destiny. But he was also the first to say 'now we are being punished' after Joseph was sold—conscience still there, only too late. Sometimes the saddest thing is not having no conscience, but having a conscience that acts too late.",
 follow=["Being the first to admit conscience's rebuke before Joseph","Once trying to rescue Joseph (proposing to put him back in the pit)"],
 caution=["Lying with his father's concubine, losing the birthright","Poorly executing the plan to rescue Joseph","Impulse bringing permanent, irreversible consequences"],
 applications=["Is there something for which you paid a long price because of a moment's impulse?","The voice of conscience and the courage to act must coexist—Reuben had conscience but lacked the power to act"],
 prayer="Lord, Reuben had the birthright, yet lost everything through one impulse. Help me pause before impulse, trusting that self-discipline is worth more than later regret. Amen."),
"犹大（雅各之子）": dict(lesson="From selling his brother to willingly taking his brother's place—this is real growth",
 summary="Jacob's fourth son, who suggested selling Joseph; his affair with Tamar exposed his moral weakness, yet after Tamar spoke the truth he admitted 'she is more righteous than I'; in old age he willingly offered himself in place of Benjamin before Joseph. One of Scripture's most authentic cases of repentant growth, from whom the Messiah came.",
 witness="He sold Joseph, yet years later stood before Joseph and said: let me stay in place of Benjamin; do not let our father suffer again. This is not the same man—or rather, this is the same man after real growth. In between he experienced the shame and confession of the Tamar incident. From selling to substituting is a real trajectory of repentance.",
 follow=["Admitting in the Tamar matter: she is more righteous than I","Willingly offering himself in place of Benjamin—the truest act of repentance","The Messiah's ancestor came from his tribe"],
 caution=["Suggesting selling Joseph into slavery","The Tamar incident showing a moral double standard"],
 applications=["In what old matter do you need, like Judah, to actively say: I am willing to bear it in another's place?","Real growth is not forgetting the past, but responding to past sin with present action"],
 prayer="Lord, Judah went from selling his brother to willingly taking his place. Help me have such a real trajectory of growth too—not only feeling remorse, but proving at the critical moment, through action, that I have changed. Amen."),
"但（雅各之子）": dict(lesson="A tribe's potential needs faithfulness to God to be realized",
 summary="Jacob's fifth son (born of Bilhah), of whom Jacob prophesied he would judge his people as one of Israel's tribes; but the tribe of Dan later became the first to introduce idolatry, migrating and setting up idol worship in Judges, and was finally omitted from the twelve tribes in Revelation.",
 witness="Jacob prayed for him: I wait for Your salvation, O LORD! This is a sigh—as if Jacob already foresaw this tribe would go astray. The title of greatest potential sometimes comes with the deepest temptation. The tribe of Dan's story reminds us: God-given potential needs obedience to be realized, or it becomes a footnote.",
 follow=["Jacob's bestowal of the title of judgment and leadership"],
 caution=["The tribe of Dan becoming the first in Israel to introduce idolatry","From its migration in Judges to being finally omitted from Revelation's list"],
 applications=["The potential God gave you—are you using it to glorify Him, or going your own way?","'I wait for Your salvation'—where do you need to stop and wait for God?"],
 prayer="Lord, the tribe of Dan had great potential, yet turned to idols. Help me not waste the potential You gave me, but return every talent and calling to You. Amen."),
"拿弗他利（雅各之子）": dict(lesson="Nimbly and freely conveying good words is God's gift",
 summary="Jacob's sixth son (born of Bilhah), of whom Jacob prophesied he was like a doe set free, bearing good news; his tribe's inheritance was in Galilee, where Isaiah prophesied the people would see a great light, and where Jesus began His ministry, fulfilling the spiritual meaning of that land.",
 witness="His own story is brief, but his tribe's inheritance became the starting point of Jesus' ministry. Sometimes a person's calling takes hundreds of years to fully appear. Jacob said: bearing good news—this prophecy was finally fully realized in Jesus in Galilee.",
 follow=["Blessed by his father Jacob as a tribe that 'gives beautiful words,' symbolizing the proclamation of the good news of the gospel (Gen 49:21)","His tribe's inheritance becoming the place where Jesus began His ministry, where 'the people sitting in darkness saw a great light,' fulfilling a centuries-old prophecy (Isa 9:1-2; Matt 4:13-16)"],
 caution=[],
 applications=["Your 'inheritance'—the place where you are—does it have a spiritual meaning God has already placed, waiting for you to discover?","Where does proclaiming the good news begin? It begins where you are"],
 prayer="Lord, Naphtali's inheritance prophesied a light hundreds of years later. Help me, where I am, faithfully convey Your good news, trusting You already have Your plan in my place. Amen."),
"迦得（雅各之子）": dict(lesson="Still triumphing under oppression is the mark of God's people",
 summary="Jacob's seventh son (born of Zilpah), of whom Jacob prophesied he would be attacked by raiders, but would triumph in the end; his tribe's inheritance was east of the Jordan, a border region that experienced real battle-testing.",
 witness="Jacob described him in just one sentence: a troop will attack him, but he will attack their heels. This is the fate of a border people—constantly attacked, but finally victorious. Sometimes God's promise is not 'you won't be attacked,' but 'though attacked, you will surely triumph.'",
 follow=["Jacob's prophecy 'Gad will be raided, but he will raid at their heels' (Gen 49:19)—though attacked, finally turning defeat into victory","His tribe's inheritance on the border east of the Jordan, often in war, living out the picture of standing firm and triumphing by God in continual conflict"],
 caution=[],
 applications=["The attack you're experiencing—God's word is: you will surely triumph","God's promise is not always 'free from suffering'; sometimes it is 'triumph through suffering'"],
 prayer="Lord, Gad's promise was not peace, but victory. Help me, in moments of attack, trust Your word: you will surely triumph. Not because I am strong, but because You are here. Amen."),
}
